import asyncio
import functools
import inspect

async def async_func():
    return "async"

def sync_func():
    return "sync"

def sync_wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

async def async_wrapper(func):
    # This is the problem. async_wrapper itself is async, but it returns a function.
    # The returned function should be the one we check.
    @functools.wraps(func)
    async def wrapped(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapped

# Wait, the async_wrapper above is async, so you have to await it to get the wrapped function.
# That's probably not how decorators are usually used.
# Usually a wrapper is a sync function that returns a wrapped function.

def async_wrapper_sync(func):
    @functools.wraps(func)
    async def wrapped(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapped

case_a = sync_wrapper(async_func)
case_b = async_wrapper_sync(sync_func)
case_c = async_wrapper_sync(async_func)
case_d = sync_wrapper(sync_func)

def is_any_async(func):
    current = func
    while True:
        if inspect.iscoroutinefunction(current):
            return True
        if isinstance(current, functools.partial):
            current = current.func
        elif hasattr(current, "__wrapped__"):
            current = current.__wrapped__
        else:
            break
    return False

print(f"Case A (sync wrap async): {is_any_async(case_a)}")
print(f"Case B (async wrap sync): {is_any_async(case_b)}")
print(f"Case C (async wrap async): {is_any_async(case_c)}")
print(f"Case D (sync wrap sync): {is_any_async(case_d)}")
EOF
